def run_agent(records, limit=2):
    trace = []
    for step, record in enumerate(records[:limit], start=1):
        trace.append(
            f"lookup {step}: {record['source']} "
            f"current={record['current']}"
        )
        if record["current"]:
            return "success", record["date"], trace, limit - step
    return "abstain", "No current delivery estimate", trace, max(0, limit - len(trace))

cached = {"source": "cache", "date": "Thursday", "current": False}
live = {"source": "order service", "date": "Friday", "current": True}

for name, records in [("Supported", [cached, live]), ("Unsupported", [cached, cached])]:
    status, answer, trace, remaining = run_agent(records)
    print(name)
    print("\n".join(trace))
    print(f"{status}: {answer}; remaining={remaining}")

