orders = {"O-204": {"owner": "U-17", "remaining": 4800}}
ledger = {}

def refund(actor, order_id, cents, key):
    if type(cents) is not int or cents <= 0:
        raise ValueError("positive integer cents required")
    order = orders[order_id]
    if actor != order["owner"]:
        raise PermissionError("not the order owner")
    fingerprint = (actor, order_id, cents)
    if key in ledger:
        original, receipt = ledger[key]
        if original != fingerprint:
            raise ValueError("idempotency key conflict")
        return receipt, "replayed"
    if cents > order["remaining"]:
        raise ValueError("amount exceeds refundable balance")
    receipt = f"R-{len(ledger) + 1:03d}"
    order["remaining"] -= cents
    ledger[key] = (fingerprint, receipt)
    return receipt, "executed"

for _ in range(2):
    receipt, status = refund("U-17", "O-204", 4800, "refund-204")
    print(status, receipt)

for actor, amount in [("U-17", 1000), ("U-99", 4800)]:
    try:
        refund(actor, "O-204", amount, "refund-204")
    except (ValueError, PermissionError) as error:
        print("rejected:", error)
print("refund writes:", len(ledger))
print("remaining cents:", orders["O-204"]["remaining"])

