DOCS = {
    "password": {"id": "D1", "text": "Open Settings, then Security, then Reset password."},
    "invoice": {"id": "D2", "text": "Open Billing and select Download PDF."},
}

def run(proposal):
    if proposal.get("name") != "search_docs":
        return {"status": "rejected", "answer": "Tool not allowed", "sources": []}
    args = proposal.get("arguments")
    if not isinstance(args, dict) or set(args) != {"topic"}:
        return {"status": "rejected", "answer": "Invalid argument fields", "sources": []}
    topic = args["topic"]
    if not isinstance(topic, str) or not topic.strip():
        return {"status": "rejected", "answer": "topic must be text", "sources": []}
    doc = DOCS.get(topic.lower())
    if doc is None:
        return {"status": "abstain", "answer": "No approved source found", "sources": []}
    return {"status": "success", "answer": doc["text"], "sources": [doc["id"]]}

cases = [
    ({"name": "search_docs", "arguments": {"topic": "password"}}, "success"),
    ({"name": "search_docs", "arguments": {"topic": "Mars"}}, "abstain"),
    ({"name": "search_docs", "arguments": {"topic": 42}}, "rejected"),
]
for proposal, expected in cases:
    result = run(proposal)
    assert result["status"] == expected
    if expected == "success":
        assert result["sources"] == ["D1"]
    else:
        assert result["sources"] == []
    print(result["status"], "|", result["answer"], "|", result["sources"])
print("3 contract tests passed")

