observations = [
    ("catalog", {"price_usd": 640}),
    ("warranty page", {"warranty_years": 2}),
]
required = {"price_usd", "warranty_years"}
evidence = {}
limit = 4
for step, (source, facts) in enumerate(observations, start=1):
    if step > limit:
        break
    missing_before = sorted(required - evidence.keys())
    before = dict(evidence)
    evidence.update(facts)
    missing_after = sorted(required - evidence.keys())
    print(f"action {step}: {source}; missing before={missing_before}")
    print(f"  missing after={missing_after}; remaining={limit - step}")
    if evidence == before:
        print("STOP: no progress")
        break
    if not missing_after:
        passed = evidence["price_usd"] <= 700 and evidence["warranty_years"] >= 2
        print("verifier:", "PASS" if passed else "FAIL")
        print("STOP: criteria checked")
        break
else:
    print("STOP: approved observations exhausted")

agent-memory.code:
memory = {}

def save(user, value, expected_version, consent, now=100):
    if not consent:
        raise PermissionError("memory consent required")
    key = (user, "report_format")
    old = memory.get(key)
    version = old["version"] if old else 0
    if version != expected_version:
        raise ValueError("stale version")
    memory[key] = {"value": value, "version": version + 1,
                   "source": "explicit user preference", "expires": now + 100}
    return memory[key]["version"]

def recall(user, now=100):
    record = memory.get((user, "report_format"))
    if record is None or now >= record["expires"]:
        return None
    return record["value"]

print("version", save("U-17", "PDF", 0, True), recall("U-17"))
print("version", save("U-17", "HTML", 1, True), recall("U-17"))
try:
    save("U-17", "PDF", 1, True)
except ValueError as error:
    print("rejected:", error)
print("other user:", recall("U-99"))
print("after expiry:", recall("U-17", now=200))
del memory[("U-17", "report_format")]
print("after forget:", recall("U-17"))

