edges = {
    "START": {"VALIDATE"},
    "VALIDATE": {"WAIT_APPROVAL"},
    "WAIT_APPROVAL": {"EXECUTE", "END"},
    "EXECUTE": {"END"},
    "END": set(),
}
state = {"stage": "START", "approved": False}
trace = ["START"]

def move(destination):
    source = state["stage"]
    if destination not in edges[source]:
        raise ValueError(f"illegal edge {source} -> {destination}")
    if destination == "EXECUTE" and not state["approved"]:
        raise PermissionError("approval required")
    state["stage"] = destination
    trace.append(destination)

move("VALIDATE")
try:
    move("EXECUTE")
except ValueError as error:
    print("blocked:", error)
move("WAIT_APPROVAL")
try:
    move("EXECUTE")
except PermissionError as error:
    print("blocked:", error)
state["approved"] = True  # fixture for an authenticated reviewer event
move("EXECUTE")
move("END")
print(" -> ".join(trace))

agentic-rag.code:
batches = [
    [{"id": "D1", "current": True, "facts": {"price_usd": 40}},
     {"id": "OLD", "current": False, "facts": {"refund_days": 90}}],
    [{"id": "D2", "current": True, "facts": {"refund_days": 30}}],
]
required = {"price_usd", "refund_days"}

def retrieve_and_check(search_results):
    evidence, sources = {}, {}
    for attempt, docs in enumerate(search_results[:2], start=1):
        print("search", attempt, "for", sorted(required - evidence.keys()))
        for doc in docs:
            if not doc["current"]:
                print(" rejected:", doc["id"], "(outdated)")
                continue
            for field, value in doc["facts"].items():
                if field in required:
                    evidence[field] = value
                    sources[field] = doc["id"]
        print(f" coverage: {len(evidence)}/{len(required)}")
        if required <= evidence.keys():
            break
    if required <= evidence.keys():
        print(f"Answer: USD {evidence['price_usd']} [{sources['price_usd']}]; "
              f"{evidence['refund_days']}-day refunds [{sources['refund_days']}]")
    else:
        print("Partial evidence:", evidence)
        print("Cannot verify:", ", ".join(sorted(required - evidence.keys())))

print("Complete run")
retrieve_and_check(batches)
print("Missing-policy run")
retrieve_and_check(batches[:1])

