workers = [
    {"name": "A", "seconds": 0.8, "facts": {"price_usd": (40, "P1")}},
    {"name": "B", "seconds": 1.2,
     "facts": {"price_usd": (45, "P2"), "refund_days": (30, "R1")}},
]
grouped = {}
for worker in workers:
    for field, (value, source) in worker["facts"].items():
        grouped.setdefault(field, []).append((value, source, worker["name"]))
for field, records in sorted(grouped.items()):
    values = {record[0] for record in records}
    status = "CONFLICT" if len(values) > 1 else "SUPPORTED"
    print(field, status, records)
join_seconds = 0.2
serial = sum(worker["seconds"] for worker in workers) + join_seconds
parallel = max(worker["seconds"] for worker in workers) + join_seconds
print(f"serial estimate: {serial:.1f} s")
print(f"ideal parallel estimate: {parallel:.1f} s")
print(f"ideal saving: {serial - parallel:.1f} s")
print("Final price answer: withheld pending source resolution")

