import json
tool = {
    "name": "read_invoice",
    "description": "Read one invoice in the authenticated account",
    "inputSchema": {"type": "object", "properties": {"invoice_id": {"type": "string"}},
                    "required": ["invoice_id"], "additionalProperties": False},
}
invoices = {"INV-42": {"account": "A-7", "amount_usd": 320}}
service_calls = 0

def invoke(request, scopes, account):
    global service_calls
    args = request["params"]["arguments"]
    if request["params"]["name"] != "read_invoice" or set(args) != {"invoice_id"}:
        message, failed = "Invalid tool request", True
    elif "invoices:read" not in scopes:
        message, failed = "insufficient_scope", True
    elif args["invoice_id"] not in invoices or invoices[args["invoice_id"]]["account"] != account:
        message, failed = "Invoice unavailable", True
    else:
        service_calls += 1
        message, failed = json.dumps(invoices[args["invoice_id"]]), False
    return {"jsonrpc": "2.0", "id": request["id"],
            "result": {"content": [{"type": "text", "text": message}], "isError": failed}}

print("client -> server: initialize (version 2025-11-25)")
print("server -> client: version and tools capability accepted (fixture)")
print("client -> server: notifications/initialized")
print("tools/list result:", json.dumps({"tools": [tool]}, sort_keys=True))
request = {"jsonrpc": "2.0", "id": 2, "method": "tools/call",
           "params": {"name": "read_invoice", "arguments": {"invoice_id": "INV-42"}}}
for scopes in [set(), {"invoices:read"}]:
    response = invoke(request, scopes, "A-7")
    print(json.dumps(response, sort_keys=True))
print("underlying service calls:", service_calls)

