from html.parser import HTMLParser

class Snapshot(HTMLParser):
    def __init__(self):
        super().__init__()
        self.buttons, self.statuses = [], []
        self.active = None

    def handle_starttag(self, tag, attrs):
        attrs = dict(attrs)
        if tag == "button":
            self.active = ["button", "", "disabled" not in attrs]
        elif attrs.get("role") == "status":
            self.active = ["status", "", True]

    def handle_data(self, text):
        if self.active:
            self.active[1] += text

    def handle_endtag(self, tag):
        if self.active and ((tag == "button" and self.active[0] == "button")
                            or (tag == "p" and self.active[0] == "status")):
            kind, text, enabled = self.active
            (self.buttons if kind == "button" else self.statuses).append((text.strip(), enabled))
            self.active = None

def inspect(html):
    parser = Snapshot()
    parser.feed(html)
    return parser

before = '<button>Save draft</button><p role="status">Unsaved</p>'
after = '<button>Save draft</button><p role="status">Draft D-17 saved</p>'
page = inspect(before)
targets = [label for label, enabled in page.buttons if label == "Save draft" and enabled]
print("unique enabled target:", len(targets) == 1)
for label, html in [("unchanged page", before), ("receipt page", after)]:
    statuses = [text for text, _ in inspect(html).statuses]
    verified = len(targets) == 1 and "Draft D-17 saved" in statuses
    print(label, "verified:", verified)

