session = {"user": "U-17", "scopes": {"invoice:read"}, "resources": {"INV-42"}}
tools = {"read_invoice": "invoice:read", "delete_invoice": "invoice:delete"}

def gate(proposal):
    tool, resource = proposal.get("tool"), proposal.get("resource")
    if tool not in tools:
        return False, "unregistered tool"
    if tools[tool] not in session["scopes"]:
        return False, "missing trusted scope"
    if resource not in session["resources"]:
        return False, "resource outside authorized set"
    return True, "allowed"

proposals = [
    {"tool": "read_invoice", "resource": "INV-42"},
    {"tool": "delete_invoice", "resource": "INV-42", "role": "admin"},
    {"tool": "read_invoice", "resource": "INV-99"},
]
for proposal in proposals:
    allowed, reason = gate(proposal)
    print(proposal["tool"], proposal["resource"], allowed, "-", reason)
for error in ["timeout", "authorization_denied"]:
    print(error, "retryable:", error in {"timeout", "temporary_unavailable"})
